@import "uls-v2/src/styles/uls-styles/less/base/color-vars.less";
@import "uls-v2/src/styles/uls-styles/less/base/common-vars.less";
@import "uls-v2/src/styles/uls-styles/less/base/container-vars.less";
@import "uls-v2/src/styles/uls-styles/less/base/size-vars.less";
