function getMasterFileContent() {
  return `// ==========================================================================
// ULS Master Entry (Per-App)
// ==========================================================================
// Import order:
// 1. ULS styles (base + components)
// 2. App overrides (highest priority)
// ==========================================================================

@import "./uls-styles.less";
@import "./overrides/uls-overrides.less";
`;
}

function ensureEntryFile(entryPath) {
  if (fs.existsSync(entryPath)) {
    return false;
  }

  const template = `// ==========================================================================
// ULS Override Entry Point
// ==========================================================================
// Automatically maintained by the ULS generators. Override files are grouped
// by type and imported below. New overrides will be inserted above the AUTO
// markers - do not remove them.
// ==========================================================================

// Base system overrides (variables, mixins, root config)
@import (optional) "base/root-config.overrides";
// ::ULS-AUTO-BASE::

// Element overrides (buttons, inputs, etc.)
// ::ULS-AUTO-ELEMENTS::

// Collection overrides (cards, accordions, etc.)
// ::ULS-AUTO-COLLECTIONS::

// Module overrides (dialogs, tables, etc.)
// ::ULS-AUTO-MODULES::

// Theme overrides
// ::ULS-AUTO-THEMES::

`;

  fs.writeFileSync(entryPath, template, 'utf8');
  console.log(`📝 Created override entry: ${path.relative(process.cwd(), entryPath)}`);
  return true;
}

function ensureRootOverride(rootOverridePath) {
  if (fs.existsSync(rootOverridePath)) {
    return false;
  }

  const content = `// ==========================================================================
// ROOT CONFIG OVERRIDES
// ==========================================================================
// Customize global CSS variables or LESS tokens here. Everything defined in
// this file loads immediately after the core ULS bundle.
// ==========================================================================

:root {
  // --uls-global-scale: 1.125;
  // --uls-primary-color: #ff0000;
}

// Example LESS override:
// @font-size14: 15px;
`;

  fs.writeFileSync(rootOverridePath, content, 'utf8');
  console.log(`📝 Created base override: ${path.relative(process.cwd(), rootOverridePath)}`);
  return true;
}

function registerRootOverrideImport(entryPath) {
  const importLine = '@import (optional) "base/root-config.overrides";';
  const marker = '// ::ULS-AUTO-BASE::';
  let contents = fs.readFileSync(entryPath, 'utf8');

  if (contents.includes(importLine)) {
    return;
  }

  if (contents.includes(marker)) {
    contents = contents.replace(marker, `${importLine}\n${marker}`);
  } else {
    contents = `${importLine}\n${contents}`;
  }

  fs.writeFileSync(entryPath, contents, 'utf8');
}

function getAppNames(config = {}) {
  const defaultApp = (config.defaultApp || DEFAULT_APP_NAME || 'default').toString().trim() || 'default';
  const rawApps = Array.isArray(config.apps) ? config.apps : [];
  const apps = rawApps
    .map((name) => (name || '').toString().trim())
    .filter(Boolean);

  const unique = new Set([defaultApp, ...apps]);
  return Array.from(unique);
}

