/**
 * Lists existing app directories under src/styles/uls/
 */
function listExistingApps(stylesPath) {
  if (!fs.existsSync(stylesPath)) {
    return [];
  }

  const entries = fs.readdirSync(stylesPath, { withFileTypes: true });
  const apps = [];

  entries.forEach((entry) => {
    if (entry.isDirectory()) {
      const appPath = path.join(stylesPath, entry.name);
      // Check if it looks like an app directory (has uls-master.less or uls-base.less)
      const hasMasterFile = fs.existsSync(path.join(appPath, 'uls-master.less')) ||
                           fs.existsSync(path.join(appPath, 'uls-base.less'));
      if (hasMasterFile) {
        apps.push(entry.name);
      }
    }
  });

  return apps.sort();
}

/**
 * Validates app name (same validation as create-uls-app.js)
 */
function validateAppName(name) {
  if (!name || name.trim() === '') {
    return false;
  }

  // Must be lowercase
  if (name !== name.toLowerCase()) {
    return false;
  }

  // No spaces
  if (name.includes(' ')) {
    return false;
  }

  // Only alphanumeric, hyphens, underscores
  if (!/^[a-z0-9_-]+$/.test(name)) {
    return false;
  }

  // Not "default" (reserved)
  if (name === 'default') {
    return false;
  }

  return true;
}

/**
 * Prompts user to select existing app or create new one
 */
async function promptAppSelection(existingApps) {
  const readline = require('readline');
  const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout,
  });

  const question = (promptText) =>
    new Promise((resolve) => {
      rl.question(promptText, (answer) => resolve(String(answer || '').trim()));
    });

  return (async () => {
    if (existingApps.length > 0) {
      console.log('\n📁 Existing ULS apps found:');
      existingApps.forEach((app, index) => {
        console.log(`  ${index + 1}. ${app}`);
      });
      console.log(`  ${existingApps.length + 1}. Create new app`);
      console.log();

      while (true) {
        const answer = await question(
          `Select app (1-${existingApps.length + 1}) or type new app name: `
        );

        // Check if it's a number (existing app selection)
        const num = parseInt(answer, 10);
        if (!isNaN(num) && num >= 1 && num <= existingApps.length) {
          rl.close();
          return { type: 'existing', appName: existingApps[num - 1] };
        }
        if (num === existingApps.length + 1) {
          // User wants to create new
          break;
        }

        // Check if it's a valid new app name
        if (validateAppName(answer)) {
          rl.close();
          return { type: 'new', appName: answer };
        }

        console.log('   ❌ Invalid selection or app name.');
        console.log('   App name must be: lowercase, no spaces, alphanumeric/hyphens/underscores only, not "default"');
      }
    }

    // No existing apps, prompt for new app name
    while (true) {
      const answer = await question('Enter new app name (lowercase, no spaces): ');
      if (validateAppName(answer)) {
        rl.close();
        return { type: 'new', appName: answer };
      }
      console.log('   ❌ Invalid app name.');
      console.log('   App name must be: lowercase, no spaces, alphanumeric/hyphens/underscores only, not "default"');
    }
  })();
}

/**
 * Copies all files from source app directory to destination app directory
 */
function copyAppFromDefault(sourceAppDir, destAppDir) {
  if (!fs.existsSync(sourceAppDir)) {
    return false;
  }

  // Create destination directory
  if (!fs.existsSync(destAppDir)) {
    fs.mkdirSync(destAppDir, { recursive: true });
  }

  let copied = false;

  function copyRecursive(src, dest) {
    const entries = fs.readdirSync(src, { withFileTypes: true });

    entries.forEach((entry) => {
      const srcPath = path.join(src, entry.name);
      const destPath = path.join(dest, entry.name);

      if (entry.isDirectory()) {
        if (!fs.existsSync(destPath)) {
          fs.mkdirSync(destPath, { recursive: true });
        }
        copyRecursive(srcPath, destPath);
        copied = true;
      } else {
        if (!fs.existsSync(destPath)) {
          fs.copyFileSync(srcPath, destPath);
          copied = true;
        }
      }
    });
  }

  copyRecursive(sourceAppDir, destAppDir);
  return copied;
}

async function resolveFrameworkChoice({ projectRoot, config, configPath }) {
  const existing = (config.framework || '').toString().trim().toLowerCase();
  if (SUPPORTED_FRAMEWORKS.includes(existing)) {
    return existing;
  }

  const selected = await promptFramework();

  // Persist into config file (per requirement)
  if (configPath) {
    try {
      upsertFrameworkInConfigFile(configPath, selected);
    } catch (err) {
      console.warn(`\n⚠️  Warning: Could not persist framework into ${path.basename(configPath)}: ${err.message}`);
    }
  }

  return selected;
}

