/**
 * Converts app structure to addon structure (minimal adjustments only)
 * Only modifies what ember init created, doesn't create new files manually
 */
async function convertToAddonStructure(projectRoot) {
  // Only convert ember-cli-build.js from EmberApp to EmberAddon if needed
  const buildConfigPath = path.join(projectRoot, 'ember-cli-build.js');
  if (fs.existsSync(buildConfigPath)) {
    let buildConfig = fs.readFileSync(buildConfigPath, 'utf8');
    // Replace EmberApp with EmberAddon if needed
    if (buildConfig.includes('EmberApp') && !buildConfig.includes('EmberAddon')) {
      buildConfig = buildConfig.replace(/EmberApp/g, 'EmberAddon');
      buildConfig = buildConfig.replace(
        /require\(['"]ember-cli\/lib\/broccoli\/ember-app['"]\)/g,
        "require('ember-cli/lib/broccoli/ember-addon')"
      );
      fs.writeFileSync(buildConfigPath, buildConfig, 'utf8');
      console.log('   📝 Updated: ember-cli-build.js (converted to addon)');
    }
  }

  // Ensure index.js has addon export (if it exists, update it; if not, ember init should have created it)
  const indexJsPath = path.join(projectRoot, 'index.js');
  if (fs.existsSync(indexJsPath)) {
    let indexJs = fs.readFileSync(indexJsPath, 'utf8');
    // Only update if it doesn't have the addon export pattern
    if (!indexJs.includes("require('./package').name")) {
      const indexJsContent = `'use strict';

module.exports = {
  name: require('./package').name,
};
`;
      fs.writeFileSync(indexJsPath, indexJsContent, 'utf8');
      console.log('   📝 Updated: index.js (addon export)');
    }
  }
}

