/**
 * Find UI package and ULS paths (generic - works for any UI repo name)
 * 
 * Detection logic:
 * 1. UI Repository: Has ULS directly in node_modules/uls-v2 → use directly
 * 2. Application Repository: Has a linked/installed UI package with ULS → use from UI package
 */
function findUiPackageForConfig(projectRoot) {
  // Prioritize nested UI packages over direct installations
  // This handles cases where both exist (e.g., bs-app has both direct uls-v2 and bs-ui with nested uls-v2)
  const nodeModulesPath = path.resolve(projectRoot, 'node_modules');
  
  if (fs.existsSync(nodeModulesPath)) {
    try {
      // Scan node_modules for packages that have ULS
      const entries = fs.readdirSync(nodeModulesPath, { withFileTypes: true });
      
      for (const entry of entries) {
        // Skip scoped packages directory (we'll check scoped packages separately)
        // Handle both directories and symlinks (symlinks show as files but are actually directories)
        if (!entry.name.startsWith('@')) {
          const candidatePath = path.resolve(nodeModulesPath, entry.name);
          
          // Check if it's a directory or symlink by trying to access it
          let isAccessible = false;
          try {
            const stats = fs.lstatSync(candidatePath);
            isAccessible = stats.isDirectory() || stats.isSymbolicLink();
          } catch (err) {
            // Not accessible, skip
            continue;
          }
          
          if (isAccessible) {
            const ulsPath = path.resolve(candidatePath, 'node_modules/uls-v2');
            
            // Check if this package has ULS
            if (fs.existsSync(ulsPath)) {
              return {
                uiPackagePath: candidatePath,
                ulsPath: ulsPath,
                useUiPackage: true
              };
            }
          }
        }
      }
      
      // Also check scoped packages (@scope/package-name)
      const scopedDirs = entries.filter(e => e.isDirectory() && e.name.startsWith('@'));
      for (const scopedDir of scopedDirs) {
        const scopedPath = path.resolve(nodeModulesPath, scopedDir.name);
        try {
          const scopedEntries = fs.readdirSync(scopedPath, { withFileTypes: true });
          for (const scopedEntry of scopedEntries) {
            if (scopedEntry.isDirectory()) {
              const candidatePath = path.resolve(scopedPath, scopedEntry.name);
              const ulsPath = path.resolve(candidatePath, 'node_modules/uls-v2');
              
              if (fs.existsSync(ulsPath)) {
                return {
                  uiPackagePath: candidatePath,
                  ulsPath: ulsPath,
                  useUiPackage: true
                };
              }
            }
          }
        } catch (err) {
          // Continue if can't read scoped directory
        }
      }
    } catch (err) {
      // Continue if can't read node_modules
    }
  }
  
  // Fallback: check relative paths (for development scenarios)
  const parentDir = path.resolve(projectRoot, '..');
  if (fs.existsSync(parentDir)) {
    try {
      const siblings = fs.readdirSync(parentDir, { withFileTypes: true });
      for (const sibling of siblings) {
        if (sibling.isDirectory() && sibling.name !== path.basename(projectRoot)) {
          const candidatePath = path.resolve(parentDir, sibling.name);
          const ulsPath = path.resolve(candidatePath, 'node_modules/uls-v2');
          
          if (fs.existsSync(ulsPath)) {
            return {
              uiPackagePath: candidatePath,
              ulsPath: ulsPath,
              useUiPackage: true
            };
          }
        }
      }
    } catch (err) {
      // Continue if can't read parent directory
    }
  }
  
  // Fallback: check if ULS is directly available (UI repository scenario)
  // Only if no nested UI package was found
  const ulsDirect = path.resolve(projectRoot, 'node_modules/uls-v2');
  if (fs.existsSync(ulsDirect)) {
    return {
      uiPackagePath: null,
      ulsPath: ulsDirect,
      useUiPackage: false
    };
  }
  
  return null;
}

function writeViteBuildConfigTemplate(projectRoot, relPaths) {
  const targetPath = path.join(projectRoot, 'vite.config.build.mjs');
  
  // Check if file exists and has old hardcoded paths that need updating
  let needsUpdate = false;
  if (fs.existsSync(targetPath)) {
    const existingContent = fs.readFileSync(targetPath, 'utf8');
    // Check if it has the old hardcoded paths pattern (multiple variations)
    const oldPatterns = [
      "resolve(__dirname, 'src/styles/uls-master.less')",
      "resolve(__dirname, \"src/styles/uls-master.less\")",
      "resolve(__dirname, 'src/styles/uls.less')",
      "resolve(__dirname, \"src/styles/uls.less\")",
      "resolve(__dirname, 'src/scripts/passthrough.js')",
      "resolve(__dirname, \"src/scripts/passthrough.js\")",
      "resolve(process.cwd(), 'styles')",
      "resolve(process.cwd(), \"styles\")",
      "src/styles/uls-master.less\"",
      "src/styles/uls-master.less'",
      "'src/styles/uls'",  // Any reference to old styles path
      "\"src/styles/uls\"",
    ];
    const hasOldPattern = oldPatterns.some(pattern => existingContent.includes(pattern));
    
    // Check if it has the new correct paths
    const hasNewPattern = existingContent.includes('src/styles/uls') || 
                          existingContent.includes('createRequire') ||
                          existingContent.includes('ulsConfig.stylesPath') ||
                          existingContent.includes('src/scripts/passthrough');
    
    if (hasOldPattern && !hasNewPattern) {
      needsUpdate = true;
      console.log(`🔄 Detected old paths in vite.config.build.mjs - updating with correct paths...`);
    } else if (hasNewPattern && !hasOldPattern) {
      // File exists and already has correct paths
      return false;
    } else if (!hasOldPattern && !hasNewPattern) {
      // File exists but doesn't match either pattern - might be custom, don't overwrite
      console.log(`⚠️  vite.config.build.mjs exists but doesn't match known patterns - skipping update`);
      return false;
    } else if (hasOldPattern && hasNewPattern) {
      // Has both - might be partially updated, update anyway to be safe
      needsUpdate = true;
      console.log(`🔄 vite.config.build.mjs has mixed patterns - updating to ensure correctness...`);
    }
  }

  // Resolve paths relative to project root
  const stylesPath = relPaths.stylesPath || 'src/styles/uls';
  const passthroughPath = relPaths.passthroughPath || 'src/scripts/passthrough.js';
  
  // Convert to forward slashes for consistency in template
  const stylesPathNormalized = stylesPath.replace(/\\/g, '/');
  const passthroughPathNormalized = passthroughPath.replace(/\\/g, '/');
  const passthroughDirNormalized = path.dirname(passthroughPathNormalized).replace(/\\/g, '/');
  
  // Detect UI package and ULS paths (generic - works for any UI repo name)
  const uiPackageInfo = findUiPackageForConfig(projectRoot)
  
  // Generate path detection code dynamically
  let ulsPathCode;
  if (uiPackageInfo && uiPackageInfo.useUiPackage) {
    // Application repo: UI package found, use ULS from UI package
    const uiPackageRelativePath = path.relative(projectRoot, uiPackageInfo.uiPackagePath);
    const uiPackageNormalized = uiPackageRelativePath.replace(/\\/g, '/');
    ulsPathCode = `// Find UI package and ULS paths (auto-detected)
const uiPackagePath = resolve(__dirname, '${uiPackageNormalized}')
const ulsPackagePath = resolve(uiPackagePath, 'node_modules/uls-v2')`;
  } else {
    // UI repo: ULS directly available
    ulsPathCode = `// Find ULS paths (UI repository - ULS installed directly)
const ulsPackagePath = resolve(__dirname, 'node_modules/uls-v2')`;
  }

  const template = `import { defineConfig } from 'vite'
import { resolve, dirname } from 'path'
import { readFileSync, writeFileSync, mkdirSync, existsSync, watch } from 'fs'
import { createRequire } from 'module'
import less from 'less'

// Load ULS config to get correct paths (using createRequire for ES modules)
let ulsConfig = {}
try {
  const configPath = resolve(__dirname, 'uls.config.cjs')
  if (existsSync(configPath)) {
    const require = createRequire(import.meta.url)
    ulsConfig = require(configPath)
  }
} catch (err) {
  console.warn('Could not load uls.config.cjs, using defaults')
}

// Resolve paths from config or use defaults (embedded at generation time)
// These defaults ensure correct paths even if config loading fails
const stylesPath = ulsConfig.stylesPath || '${stylesPathNormalized}'
const passthroughPath = ulsConfig.passthroughPath || '${passthroughPathNormalized}'

// Resolve app bundle name
// Priority: ULS_APP env var -> uls.config.cjs defaultApp -> 'default'
const appName = (process.env.ULS_APP || ulsConfig.defaultApp || '${DEFAULT_APP_NAME}').toString().trim() || '${DEFAULT_APP_NAME}'

// Global file watchers (persist across rebuilds in watch mode)
let globalLessFileWatchers = []
let globalRebuildTimeout = null

// Find UI package and ULS paths (auto-detected)
${ulsPathCode}

// Custom LESS build plugin (regular + minified)
// Supports Tailwind-like auto-rebuild when content files change
function lessBuildPlugin(options = {}) {
  const { entry, outDir, outFile, outMinFile } = options
  
  // Extract CSS compilation logic for reuse in watch mode
  const compileCSS = async (pluginContext) => {
    if (!existsSync(entry)) {
      pluginContext.error(\`Entry file not found: \${entry}\`)
      return
    }
    
    if (!existsSync(outDir)) {
      mkdirSync(outDir, { recursive: true })
    }
    
    const src = readFileSync(entry, 'utf8')
    const entryDir = resolve(entry, '..')
    const nodeModulesPath = resolve(__dirname, 'node_modules')
    const stylesRoot = resolve(process.cwd(), stylesPath)
    const appRoot = resolve(stylesRoot, appName)
    const appOverridesPath = resolve(appRoot, 'overrides')
    const ulsStylesPath = resolve(ulsPackagePath, 'src/styles')
    const ulsOverridesPath = resolve(ulsStylesPath, 'uls-overrides/less/uls-primereact')
    
    const cssResult = await less.render(src, {
      filename: entry,
      paths: [
        entryDir, 
        appRoot,
        appOverridesPath, // App overrides directory for relative imports
        stylesRoot,
        ulsStylesPath, // ULS base styles
        ulsOverridesPath, // ULS's own overrides directory for relative imports
        nodeModulesPath,
        resolve(process.cwd(), 'node_modules'),
        ${uiPackageInfo && uiPackageInfo.useUiPackage ? "resolve(uiPackagePath, 'node_modules')," : ''}
      ],
    })
    
    if (!cssResult || !cssResult.css) {
      pluginContext.error('LESS compilation failed: No CSS output')
      return
    }
    
    let css = cssResult.css
    
    writeFileSync(outFile, css, 'utf8')
    console.log(\`✅ LESS compiled → \${outFile}\`)

    // Minified CSS
    const minResult = await less.render(src, {
      filename: entry,
      paths: [
        entryDir, 
        appRoot,
        appOverridesPath, // App overrides directory for relative imports
        stylesRoot,
        ulsStylesPath, // ULS base styles
        ulsOverridesPath, // ULS's own overrides directory for relative imports
        nodeModulesPath,
        resolve(process.cwd(), 'node_modules'),
        ${uiPackageInfo && uiPackageInfo.useUiPackage ? "resolve(uiPackagePath, 'node_modules')," : ''}
      ],
      compress: true,
    })
    
    if (!minResult || !minResult.css) {
      pluginContext.error('LESS minification failed: No CSS output')
      return
    }
    
    let minCss = minResult.css
    
    writeFileSync(outMinFile, minCss, 'utf8')
    console.log(\`✅ LESS minified → \${outMinFile}\`)
  }
  
  return {
    name: 'less-build',
    async buildStart() {
      try {
        if (!entry) {
          this.error('Entry file is required')
          return
        }
        
        // Add entry file to watch list
        if (entry && existsSync(entry)) {
          this.addWatchFile(entry)
        }
        
        // Watch LESS files in ULS package and override directories
        try {
          const { glob } = await import('glob')
          
          // Watch ULS core LESS files
          const ulsStylesPath = resolve(ulsPackagePath, 'src/styles')
          if (existsSync(ulsStylesPath)) {
            try {
              const ulsLessFiles = glob.sync(\`\${ulsStylesPath}/**/*.less\`, {
                ignore: ['node_modules/**', 'dist/**'],
                absolute: true
              })
              ulsLessFiles.forEach(file => {
                if (existsSync(file)) {
                  this.addWatchFile(file)
                }
              })
              console.log(\`👀 Watching \${ulsLessFiles.length} ULS LESS files\`)
            } catch (err) {
              // Continue if glob fails
            }
          }
          
          // Watch user override LESS files (from stylesPath config)
          const userStylesPath = resolve(process.cwd(), stylesPath)
          if (existsSync(userStylesPath)) {
            try {
              const userLessFiles = glob.sync(\`\${userStylesPath}/**/*.less\`, {
                ignore: ['node_modules/**', 'dist/**'],
                absolute: true
              })
              userLessFiles.forEach(file => {
                if (existsSync(file)) {
                  this.addWatchFile(file)
                  
                  // Set up direct file watcher as backup (for watch mode)
                  // This ensures CSS rebuilds even if watchChange hook isn't called
                  try {
                    const pluginContext = this
                    // Only add if not already watching this file
                    const alreadyWatching = globalLessFileWatchers.some(w => w.path === file)
                    if (!alreadyWatching) {
                      const watcher = watch(file, { persistent: true }, (eventType) => {
                        if (eventType === 'change') {
                          console.log(\`📝 LESS file changed: \${file}\`)
                          console.log(\`🔄 Rebuilding CSS...\`)
                          
                          // Debounce rebuilds
                          if (globalRebuildTimeout) {
                            clearTimeout(globalRebuildTimeout)
                          }
                          
                          globalRebuildTimeout = setTimeout(async () => {
                            try {
                              await compileCSS(pluginContext)
                              console.log(\`✨ CSS updated automatically!\`)
                            } catch (err) {
                              console.error(\`❌ Failed to rebuild CSS:\`, err.message)
                            }
                          }, 200) // 200ms debounce
                        }
                      })
                      
                      globalLessFileWatchers.push({ watcher, path: file })
                    }
                  } catch (err) {
                    // File watching might fail, continue
                  }
                }
              })
              if (userLessFiles.length > 0) {
                console.log(\`👀 Watching \${userLessFiles.length} user override LESS files\`)
              }
            } catch (err) {
              // Continue if glob fails
            }
          }
          
          // Watch override files in uls-overrides directory (common pattern)
          const overridesPath = resolve(process.cwd(), 'uls-overrides')
          if (existsSync(overridesPath)) {
            try {
              const overrideLessFiles = glob.sync(\`\${overridesPath}/**/*.less\`, {
                ignore: ['node_modules/**', 'dist/**'],
                absolute: true
              })
              overrideLessFiles.forEach(file => {
                if (existsSync(file)) {
                  this.addWatchFile(file)
                }
              })
              if (overrideLessFiles.length > 0) {
                console.log(\`👀 Watching \${overrideLessFiles.length} override LESS files\`)
              }
            } catch (err) {
              // Continue if glob fails
            }
          }
          
          // Watch override files in ULS package's override directory
          const ulsOverridesPath = resolve(ulsPackagePath, 'src/styles/uls-overrides')
          if (existsSync(ulsOverridesPath)) {
            try {
              const ulsOverrideLessFiles = glob.sync(\`\${ulsOverridesPath}/**/*.less\`, {
                ignore: ['node_modules/**', 'dist/**'],
                absolute: true
              })
              ulsOverrideLessFiles.forEach(file => {
                if (existsSync(file)) {
                  this.addWatchFile(file)
                }
              })
              if (ulsOverrideLessFiles.length > 0) {
                console.log(\`👀 Watching \${ulsOverrideLessFiles.length} ULS override LESS files\`)
              }
            } catch (err) {
              // Continue if glob fails
            }
          }
        } catch (err) {
          // glob might not be available, continue without watching LESS files
        }
        
        // Compile CSS during build
        // Note: buildStart hook is only called by Rollup during 'vite build', not during 'npx uls init'
        // So this won't create dist folder during init, only during actual builds
        await compileCSS(this)
      } catch (error) {
        const errorMessage = error?.message || error?.toString() || 'Unknown error'
        const errorStack = error?.stack || ''
        this.error(\`LESS compilation failed: \${errorMessage}\${errorStack ? '\\n' + errorStack : ''}\`)
        throw error
      }
    },
    // Auto-rebuild when LESS files change (Rollup watch mode)
    watchChange(id) {
      const isLessFile = id.endsWith('.less')
      
      if (isLessFile) {
        console.log(\`📝 LESS file changed: \${id}\`)
        console.log(\`🔄 Rebuilding CSS...\`)
        
        // Use setTimeout to debounce and avoid multiple rebuilds
        if (this._rebuildTimeout) {
          clearTimeout(this._rebuildTimeout)
        }
        
        this._rebuildTimeout = setTimeout(async () => {
          try {
            await compileCSS(this)
            console.log(\`✨ CSS updated automatically!\`)
          } catch (err) {
            console.error(\`❌ Failed to rebuild CSS:\`, err.message)
          }
        }, 100) // 100ms debounce
      }
    },
    closeWatcher() {
      // Clean up timeout when watcher closes
      if (this._rebuildTimeout) {
        clearTimeout(this._rebuildTimeout)
      }
      if (globalRebuildTimeout) {
        clearTimeout(globalRebuildTimeout)
      }
      
      // Close all file watchers
      globalLessFileWatchers.forEach(({ watcher }) => {
        try {
          watcher.close()
        } catch (err) {
          // Ignore errors when closing watchers
        }
      })
      globalLessFileWatchers = []
    },
  }
}

export default defineConfig(({ mode }) => {
  const config = {
    plugins: [],
    build: {
      emptyOutDir: false, // Keep both CSS and JS outputs
    },
  }

  // Resolve entry files - use user's local uls-master.less if it exists, otherwise fallback to ULS package
  const userLessMaster = resolve(process.cwd(), stylesPath, appName, 'uls-master.less')
  const lessEntry = mode === 'less-only'
    ? (existsSync(userLessMaster) ? userLessMaster : resolve(ulsPackagePath, 'src/styles/uls.less'))
    : (existsSync(userLessMaster) ? userLessMaster : resolve(ulsPackagePath, 'src/styles/uls-master.less'))
  const passthroughEntry = resolve(__dirname, passthroughPath)
  
  // Per-app CSS output names
  const cssOutFile = resolve(__dirname, \`dist/css/uls-\${appName}.css\`)
  const cssOutMinFile = resolve(__dirname, \`dist/css/uls-\${appName}.min.css\`)

  // LESS-only modes
  if (mode === 'less' || mode === 'less-only') {
    // Validate entry file exists
    if (!existsSync(lessEntry)) {
      console.error(\`❌ Error: LESS entry file not found: \${lessEntry}\`)
      console.error(\`   Expected path: \${lessEntry}\`)
      console.error(\`   Styles path from config: \${stylesPath}\`)
      console.error(\`   Current directory: \${__dirname}\`)
      throw new Error(\`LESS entry file not found: \${lessEntry}\`)
    }
    
    config.plugins.push(
      lessBuildPlugin({
        entry: lessEntry,
        outDir: resolve(__dirname, 'dist/css'),
        outFile: cssOutFile,
        outMinFile: cssOutMinFile,
      })
    )
    // Disable JS build in LESS-only mode
    config.build.lib = false
    // Provide a dummy input to satisfy Rollup (plugins handle actual compilation)
    // Create a minimal dummy file if passthrough doesn't exist (only during build, not during init)
    const dummyInput = resolve(__dirname, passthroughPath)
    // Note: Don't create dummy file during init - only create during actual build
    // The build process will handle creating necessary files
    config.build.rollupOptions = {
      input: dummyInput,
      external: ['primereact/utils'],
      output: {
        format: 'es',
        // Suppress JS output - we only want CSS from the plugin
        entryFileNames: () => '.vite-temp/empty.js',
      }
    }
    return config
  }

  // JS-only mode
  if (mode === 'js') {
    config.build = {
      lib: {
        entry: passthroughEntry,
        name: 'ULSPassthrough',
        fileName: () => \`passthrough.js\`,
        formats: ['es'],
      },
      outDir: resolve(__dirname, 'dist/js'),
      minify: true,
      emptyOutDir: false,
      rollupOptions: {
        external: ['primereact/utils'],
        output: {
          format: 'es',
          entryFileNames: 'passthrough.js',
        },
      },
    }
    return config
  }

  // Default: build both LESS and JS (JS is optional)
  // Validate entry file exists
  if (!existsSync(lessEntry)) {
    console.error(\`❌ Error: LESS entry file not found: \${lessEntry}\`)
    console.error(\`   Expected path: \${lessEntry}\`)
    console.error(\`   Styles path from config: \${stylesPath}\`)
    console.error(\`   Current directory: \${__dirname}\`)
    throw new Error(\`LESS entry file not found: \${lessEntry}\`)
  }
  
  // Add LESS build plugin
  config.plugins.push(
    lessBuildPlugin({
      entry: lessEntry,
      outDir: resolve(__dirname, 'dist/css'),
      outFile: cssOutFile,
      outMinFile: cssOutMinFile,
    })
  )

  // Build JS only if passthrough file exists
  if (existsSync(passthroughEntry)) {
    config.build.lib = {
      entry: passthroughEntry,
      name: 'ULSPassthrough',
      fileName: () => \`passthrough.js\`,
      formats: ['es'],
    }
    config.build.outDir = resolve(__dirname, 'dist/js')
    config.build.minify = true
    config.build.rollupOptions = {
      external: ['primereact/utils'],
      output: {
        format: 'es',
        entryFileNames: 'passthrough.js',
      },
    }
  } else {
    // Passthrough doesn't exist - skip JS build, create dummy input for Rollup
    console.warn(\`⚠️  Passthrough file not found: \${passthroughEntry}\`)
    console.warn(\`   Skipping JS build. Only CSS will be generated.\`)
    console.warn(\`   Tip: Run 'npm run uls-passthrough' to create the passthrough file\`)
    
    // Create a minimal dummy file for Rollup (only during build, not during init)
    const dummyInput = resolve(__dirname, passthroughPath)
    // Note: Don't create dummy file during init - only create during actual build
    // The build process will handle creating necessary files
    
    config.build.lib = false
    config.build.rollupOptions = {
      input: dummyInput,
      external: ['primereact/utils'],
      output: {
        format: 'es',
        // Suppress JS output - we only want CSS from the plugin
        entryFileNames: () => '.vite-temp/empty.js',
      },
    }
  }

  return config
})
`;

  fs.writeFileSync(targetPath, template, 'utf8');
  if (needsUpdate) {
    console.log(`🛠️  Updated Vite build config: ${path.relative(process.cwd(), targetPath)}`);
  } else {
    console.log(`🛠️  Created Vite build config: ${path.relative(process.cwd(), targetPath)}`);
  }
  return true;
}

function logSummary({
  projectRoot,
  masterCreated,
  baseCreated,
  stylesCreated,
  entryCreated,
  rootOverrideCreated,
  passthroughCopied,
  configCreated,
  viteConfigCreated,
  seededOverrides,
  seededDemoPrimereact,
  seededDemoEmber,
  seededDemoComponents,
  packageJsonCreated,
  paths,
  appNames,
  framework,
}) {
  console.log('\n✅ ULS initialization complete\n');
  console.log('Scaffolded paths:');
  console.log(`   Styles directory:   ${paths.stylesPath}`);
  console.log(`   Apps directory:     ${paths.stylesPath}`);
  if (Array.isArray(appNames) && appNames.length) {
    console.log(`   Apps:               ${appNames.join(', ')}`);
  }
  if (passthroughCopied) {
    console.log(`   Passthrough:        ${paths.passthroughPath}`);
  }
  if (framework === 'primereact') {
    console.log(`   Demo PrimeReact:    ${paths.demoPrimereactPath}`);
  } else if (framework === 'ember') {
    console.log(`   Demo Ember:         ${paths.demoEmberPath}`);
  }
  console.log(`   Demo Components:   ${paths.demoComponentsPath}`);

  console.log('\nCreated artifacts:');
  if (framework === 'ember') {
    console.log('   • Ember addon structure at project root');
    console.log('   • addon/ (addon code)');
    console.log('   • app/ (app-level overrides)');
    console.log('   • tests/ (test files)');
    console.log('   • index.js (addon entry point)');
    console.log('   • ember-cli-build.js (configured for LESS)');
    console.log('   • package.json (addon package config)');
    console.log('   • src/styles/ (ULS styles directory)');
    console.log('   • src/scripts/ (scripts directory)');
    console.log('   • app/styles/app.less (app-level styles with ULS import)');
  }
  if (baseCreated) console.log('   • per-app uls-base.less');
  if (stylesCreated) console.log('   • per-app uls-styles.less');
  if (masterCreated) console.log('   • per-app uls-master.less');
  if (entryCreated) console.log('   • per-app overrides entry (uls-overrides.less)');
  if (rootOverrideCreated) console.log('   • per-app overrides/base/root-config.overrides.less');
  if (passthroughCopied) console.log(`   • passthrough.js (${paths.passthroughPath})`);
  if (seededOverrides) console.log('   • bundled override templates copied');
  if (framework === 'primereact' && seededDemoPrimereact) console.log('   • demo uls-primereact templates copied');
  if (framework === 'ember' && seededDemoEmber) console.log('   • demo uls-ember templates copied');
  if (seededDemoComponents) console.log('   • demo components templates copied');
  if (configCreated) console.log('   • uls.config.cjs');
  if (viteConfigCreated) console.log('   • vite.config.build.mjs');
  if (packageJsonCreated) console.log('   • package.json (with ULS dependency)');

  if (!passthroughCopied && !seededOverrides && !seededDemoPrimereact && !seededDemoEmber && !seededDemoComponents && !packageJsonCreated) {
    console.log('   No files overwritten; existing setup confirmed.');
  }

  console.log('\nNext steps:');
  if (framework === 'ember') {
    console.log('   1. Ember addon structure has been created at project root.');
    console.log('   2. Old src/components/ has been removed.');
    console.log('   3. Project root is now an Ember addon (uls-components/)');
    console.log('   4. ULS styles are integrated in app/styles/app.less');
    console.log('   5. Run: npm install (at project root)');
    console.log('   6. The addon will automatically include ULS styles when built');
    console.log('   7. Customize src/styles/uls/<appName>/overrides/ for app-specific overrides.');
    console.log('   8. Use ember-cli-build.js for build configuration.\n');
  } else if (packageJsonCreated) {
    console.log('   1. Dependencies have been installed automatically.');
    console.log('   2. Import src/styles/uls/<appName>/uls-master.less in your app build.');
    console.log('   3. Run npm run uls-override to add app-specific overrides.');
    console.log('   4. Customize <appName>/overrides/base/root-config.overrides.less as needed.\n');
  } else {
    console.log('   1. Import src/styles/uls/<appName>/uls-master.less in your app build.');
    console.log('   2. Run npm run uls-override to add app-specific overrides.');
    console.log('   3. Customize <appName>/overrides/base/root-config.overrides.less as needed.\n');
  }
}


